mmission":"tour affiliate ~8–12% (guided version)","accessed":"2026-07-04","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary"},"commission_pct_low":8,"commission_pct_high":12,"commission_lane":["affiliate","guide"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Museo Regional de la Cerámica / Premio Nacional de la Cerámica","si_tag":"Culture & Heritage","status":"future","hook":"National ceramics-prize museum in Centro Cultural El Refugio","bookable_category":"attraction","tier":"essential","source":"https://www.afar.com/magazine/in-guadalajara-young-designers-are-putting-a-modern-spin-on-traditional-ceramics (Accessed 2026-07-04)","si":"culture","blurb":"National ceramics-prize museum in Centro Cultural El Refugio","commission":"via tour package only (entry non-commissionable)","accessed":"2026-07-04","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary"},"commission_lane":["package"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Tlaquepaque + Tonalá private pottery tour with clay workshop","si_tag":"Culture & Heritage","status":"future","hook":"Hands-on half-day across both craft towns","bookable_category":"tour","tier":"comfort","source":"https://www.pelago.com/en-US/activity/p4g83fk6p-tonala-tlaquepaque-tour-art-towns-pottery-experience-guadalajara/ (Accessed 2026-07-04)","si":"culture","blurb":"Hands-on half-day across both craft towns","commission":"tour affiliate ~8–12%","accessed":"2026-07-04","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary"},"commission_pct_low":8,"commission_pct_high":12,"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"El Parián","si_tag":"Culinary / Nightlife","statu